_METH_H2 = {"H_WHAT", "H_WHERE", "H_HOW", "H_FMT", "H_DBL", "H_LANG", "H_QRY", "H_REPRO", "H_LIM", "H_SRC"}
_METH_PSUB = {"P_WHAT", "P_WHERE", "P_HOW", "P_FMT", "P_DBL", "P_LANG", "P_QRY", "P_REPRO"}
_METH_PHINT = {"P_CAT", "P_SRC", "TLEGEND", "CITE_RULE", "CITE_EX"}
_METH_CODE = {"C1", "C2", "LC1", "LC2", "LC3", "LC4"}
_METH_DESC = {"D1", "D2", "LD1", "LD2", "LD3", "LD4"}


def _meth_wrap(k: str) -> tuple[str, str]:
    if k == "TITLE":
        return ('<title>', '</title>')
    if k == "B":
        return ('<span class="badge">', '</span>')
    if k == "T":
        return ('<h1>', '</h1>')
    if k == "SUB":
        return ('<p>', '</p>')
    if k in _METH_H2:
        return ('<h2>', '</h2>')
    if k in _METH_PHINT:
        return ('<p class="hint">', '</p>')
    if k in _METH_PSUB:
        return ('<p class="sub">', '</p>')
    if k in _METH_DESC:
        return ('<div class="desc">', '</div>')
    if k in _METH_CODE:
        # Item labels are plain-language headings, marked up as <strong> (not <code>)
        # so screen readers don't announce them as code.
        return ('<strong>', '</strong>')
    raise KeyError(k)


