# The three pages reuse several strings verbatim from the snap page (Loading…,
# Trends, the query-builder hint, the snapshot/citation mechanics …) — inherit
# those pairs from the snap block instead of duplicating the translations. A
# pair is inherited only when its find-string actually occurs in the page.
_INHERIT_FROM_SNAP = (
    "Loading…",
    "Trends",
    "Section",
    "Reported values",
    " snapshot",
    ", dataset version ",
    "Failed to load section coverage: ",
    'Refine or extend these in the <a href="/reports">query builder</a> (pin a <code>section</code> before aggregating), browse the full field list on the <a href="/schema">Schema</a> page, or read the <a href="/methodology">Methodology</a>.',
)
for _slug in ("india", "korea", "taiwan"):
    _page = _slug + ".html"
    _page_text = open(os.path.join(STATIC, _page), encoding="utf-8").read()
    for _loc in _NEW_PAGE_LOCALES:
        _snap_pairs = dict(PAGES[_loc]["snap.html"])
        _own_finds = {_old for _old, _ in PAGES[_loc][_page]}
        for _key in _INHERIT_FROM_SNAP:
            if _key in _snap_pairs and _key in _page_text and _key not in _own_finds:
                PAGES[_loc][_page].append((_key, _snap_pairs[_key]))

# The Korea page pins a metric (not a section), so derive its hint pair from
# the snap hint translation with the pinned field name swapped.
_HINT_SECTION = 'Refine or extend these in the <a href="/reports">query builder</a> (pin a <code>section</code> before aggregating), browse the full field list on the <a href="/schema">Schema</a> page, or read the <a href="/methodology">Methodology</a>.'
for _loc in _NEW_PAGE_LOCALES:
    _snap_pairs = dict(PAGES[_loc]["snap.html"])
    if _HINT_SECTION in _snap_pairs:
        PAGES[_loc]["korea.html"].append(
            (_HINT_SECTION.replace("<code>section</code>", "<code>metric</code>"),
             _snap_pairs[_HINT_SECTION].replace("<code>section</code>", "<code>metric</code>")))


