# Fan out the shared short heads, then inherit the strings these pages reuse
# verbatim from the snap and korea blocks (Loading…, Trends, table heads,
# the query-builder hint, the snapshot/citation mechanics …).
_PAGE_SHARED2 = {
    "user-data.html": ["Dataset", "Requests", "Legal process", "Product",
                       "Lower bound", "Upper bound", "What the export covers"],
    "microsoft.html": ["Requests"],
    "linkedin.html": ["Dataset", "Requests"],
}
for _loc in _NEW_PAGE_LOCALES:
    for _page, _keys in _PAGE_SHARED2.items():
        PAGES[_loc][_page].extend((_k, _SHARED2[_loc][_k]) for _k in _keys)

_INHERIT_SOURCES2 = ("snap.html", "korea.html")
for _slug in ("user-data", "microsoft", "linkedin"):
    _page = _slug + ".html"
    _page_text = open(os.path.join(STATIC, _page), encoding="utf-8").read()
    for _loc in _NEW_PAGE_LOCALES:
        _pool: dict[str, str] = {}
        for _src in _INHERIT_SOURCES2:
            for _old, _new in PAGES[_loc][_src]:
                _pool.setdefault(_old, _new)
        _own_finds = {_old for _old, _ in PAGES[_loc][_page]}
        for _key in (*_INHERIT_FROM_SNAP,
                     "Interactive views of the reported figures. Each chart has a text alternative for screen readers.",
                     "What the report covers", "Half-year", "Country",
                     "Metric", "Total"):
            if _key in _pool and _key in _page_text and _key not in _own_finds:
                PAGES[_loc][_page].append((_key, _pool[_key]))

# The user-data and linkedin pages pin a dataset (not a section) — derive their
# hint pair from the snap hint translation with the pinned field name swapped.
for _loc in _NEW_PAGE_LOCALES:
    _snap_pairs = dict(PAGES[_loc]["snap.html"])
    if _HINT_SECTION in _snap_pairs:
        _hint_dataset = (_HINT_SECTION.replace("<code>section</code>", "<code>dataset</code>"),
                         _snap_pairs[_HINT_SECTION].replace("<code>section</code>", "<code>dataset</code>"))
        PAGES[_loc]["user-data.html"].append(_hint_dataset)
        PAGES[_loc]["linkedin.html"].append(_hint_dataset)


def check_inline_js(path: str, text: str) -> None:
    """Syntax-check every inline <script> of a written page with `node --check`.

    A translation containing an apostrophe (e.g. "Catégorie d'infraction")
    dropped into a single-quoted JS literal kills the page's entire script —
    this happened to fr/apple, fr/snap and (via quote-eating pairs) ja/zh/ko
    github before this guard existed. Skips quietly when node isn't installed.
    """
    import re as _re
    import shutil as _shutil
    import subprocess as _subprocess
    import tempfile as _tempfile
    if not _shutil.which("node"):
        return
    for script in _re.findall(r"<script>\n([\s\S]*?)</script>", text):
        with _tempfile.NamedTemporaryFile("w", suffix=".js", delete=False,
                                          encoding="utf-8") as f:
            f.write(script)
            tmp = f.name
        try:
            r = _subprocess.run(["node", "--check", tmp],
                                capture_output=True, text=True)
            if r.returncode != 0:
                raise SystemExit(
                    f"{path}: localized inline script has a JS syntax error "
                    f"(a translation likely broke a quoted literal):\n"
                    + r.stderr.replace(tmp, path)
                )
        finally:
            os.unlink(tmp)


def main(argv: list[str]) -> int:
    targets = argv[1:] or [code for code, _ in LANGS if code != "en"]
    # Always re-emit English in place so the in-site switcher stays in sync.
    locales = ["en"] + [t for t in targets if t != "en"]
    for locale in locales:
        for page in PAGES_FILES:
            src = os.path.join(STATIC, page)
            with open(src, encoding="utf-8") as f:
                text = f.read()
            out = localize(text, locale, page)
            if locale == "en":
                dest = src
            else:
                dest_dir = os.path.join(STATIC, locale)
                os.makedirs(dest_dir, exist_ok=True)
                dest = os.path.join(dest_dir, page)
            with open(dest, "w", encoding="utf-8") as f:
                f.write(out)
            check_inline_js(dest, out)
            print(f"wrote {os.path.relpath(dest, ROOT)}")
    return 0


