    _sg_text = open(os.path.join(STATIC, "singapore.html"), encoding="utf-8").read()
    _sg_own = {_o for _o, _ in PAGES[_loc]["singapore.html"]}
    _SG_FILTERS = ("singapore_metrics", "action_rate", "time_to_action",
                   "flags_received_sg", "videos_removed_sg", "content_actioned_sg",
                   "platform_report")
    for _src in ("cser.html", "microsoft.html", "india.html", "snap.html"):
        for _o, _n in PAGES[_loc][_src]:
            if _o in _sg_text and _o not in _sg_own \
                    and not any(_o in _f for _f in _SG_FILTERS):
                PAGES[_loc]["singapore.html"].append((_o, _n))
                _sg_own.add(_o)


